import{_ as a,C as n,o as e,c as r,a2 as d,b as l,w as t,a as s,E as i,a3 as p}from"./chunks/framework.C66fElYV.js";const b=JSON.parse('{"title":"Solon-Flow 迁移到 Go 的设计（flow-go）：总览","description":"","frontmatter":{},"headers":[],"relativePath":"arch/flow/00-overview.md","filePath":"arch/flow/00-overview.md","lastUpdated":1787488789000}'),g={name:"arch/flow/00-overview.md"};function f(h,o,u,w,m,v){const c=n("Mermaid");return e(),r("div",null,[o[1]||(o[1]=d(`<h1 id="solon-flow-迁移到-go-的设计-flow-go-总览" tabindex="-1">Solon-Flow 迁移到 Go 的设计（flow-go）：总览 <a class="header-anchor" href="#solon-flow-迁移到-go-的设计-flow-go-总览" aria-label="Permalink to &quot;Solon-Flow 迁移到 Go 的设计（flow-go）：总览&quot;">​</a></h1><blockquote><p>本文是「Solon-Flow 迁移到 Go」系列的第一篇（总览与可行性）。 配套：<a href="./01-go-comparison.html"><code>01-go-comparison.md</code></a>（Java→Go 逐项对照）、<a href="./02-core-design.html"><code>02-core-design.md</code></a>（核心引擎设计）、<a href="./03-config-and-eval.html"><code>03-config-and-eval.md</code></a>（配置 / 快照 / 表达式 / 集成）、<a href="./04-workflow-design.html"><code>04-workflow-design.md</code></a>（工作流子系统）、<a href="./05-tdd-plan.html"><code>05-tdd-plan.md</code></a>（TDD 路线图与分期）。 源码参照：<code>/Users/airhead/WorkSpace/goldsyear/solon-flow</code>（<code>solon-flow</code> 3.9.x + <code>solon-flow-workflow</code>）。 目标宿主：<code>aifei-go</code> 工作区（Go 1.26，零外部依赖，多模块）。</p><p>本文<strong>不写实现代码</strong>，只给出：solon-flow 是什么、迁什么不迁什么、概念词典、模块地图、可行性结论、设计原则——作为后续逐篇的<strong>契约</strong>。</p></blockquote><hr><h2 id="_0-tl-dr-设计摘要" tabindex="-1">0. TL;DR（设计摘要） <a class="header-anchor" href="#_0-tl-dr-设计摘要" aria-label="Permalink to &quot;0. TL;DR（设计摘要）&quot;">​</a></h2><ul><li><strong>能忠实迁移约 90%</strong>：图模型（Graph/Node/Link + 扁平 <code>layout</code>）、节点类型（start/end/activity/exclusive/inclusive/parallel/loop）、核心遍历引擎（<code>eval</code> → <code>node_run</code> 递归 + <code>reverting</code> 恢复）、驱动机制（<code>FlowDriver</code> 的 <code>onNodeStart/onNodeEnd/handleCondition/handleTask</code>）、<code>@/#/$</code> 前缀派发、<code>FlowContext</code> 变量域 + <code>with</code> 方法作用域、<code>FlowTrace</code>/<code>NodeRecord</code> 断点恢复、快照序列化（中断/恢复）、拦截器链、子图调用、步数预算、工作流子系统（claim/find/submit + 状态仓储 + 状态控制器）——这些都能在 Go 中以<strong>等价语义</strong>实现。</li><li><strong>唯一无法 1:1 的是「脚本任务」的任意 Java 语句求值</strong>：solon-flow 用 liquor 的 <code>Scripts.eval</code> 执行 <code>task: &quot;context.put(...)&quot;</code> 这类<strong>语句级</strong>脚本；Go 没有可用的零成本内嵌解释器。<strong>对策</strong>：默认 <code>Evaluation</code> 用 <code>aifei-go</code> 自带的 <strong><code>enjoy</code> 表达式引擎</strong>覆盖 <code>when:</code> 条件与绝大多数表达式/赋值任务（enjoy 本身支持方法调用、赋值、三元、null-safe）；纯语句脚本走 <strong><code>Container</code> 组件引用（<code>@bean</code>）</strong>——后者本就是生产环境推荐路径（类型安全、可测试）。<code>Evaluation</code> 是 2 方法接口，任意第三方引擎（yaegi 等）可后续插入。</li><li><strong>定位</strong>：作为 <code>aifei-go</code> 生态的新模块 <strong><code>./flow</code></strong>（<code>github.com/crazy-airhead/aifei-go/flow</code>），<strong>零外部依赖</strong>（仅 Go 标准库 + 内部 <code>enjoy</code> + <code>dami</code>），填补「<strong>流程编排 / 规则引擎 / 可中断可恢复工作流</strong>」的空白，与现有 <code>dami</code>（进程内事件总线）、<code>nami</code>（RPC）、<code>kafka</code>（跨进程消息）互补。</li><li><strong>关键设计原则</strong>：①「接口默认方法」→ 小接口 + 可嵌入的 base struct；②<code>@FunctionalInterface</code> → Go func 类型；③<code>ConcurrentHashMap</code>/<code>volatile</code>/<code>AtomicInteger</code> → <code>sync.RWMutex</code> / <code>atomic.Bool</code> / <code>atomic.Int64</code>；④<code>CountDownLatch + AtomicReference&lt;Throwable&gt;</code> → <code>errgroup</code>（并行网关首错优先）；⑤Solon IoC（<code>@Configuration</code>/<code>@Bean</code>/<code>getBean</code>）→ <code>MapContainer</code> + 命令式 <code>aifei.Plugin</code> 装配；⑥<code>snack4</code> + <code>snakeyaml</code> → <code>encoding/json</code> + <code>yaml.v3</code>；⑦异常 → <code>error</code> + 哨兵 <code>flow.Error</code>。</li></ul><hr><h2 id="_1-solon-flow-是什么" tabindex="-1">1. solon-flow 是什么 <a class="header-anchor" href="#_1-solon-flow-是什么" aria-label="Permalink to &quot;1. solon-flow 是什么&quot;">​</a></h2><p><code>solon-flow</code> 是面向全场景的 <strong>Java 流程编排框架</strong>，Solon 项目的一部分（亦可嵌入 SpringBoot / jFinal / Vert.X 等）。核心理念：<strong>用扁平的 YAML/JSON「点 + 线」描述一个有向图，由引擎驱动执行</strong>。</p><p>支持已知流程编排的各种场景：</p><table tabindex="0"><thead><tr><th>场景</th><th>说明</th><th>solon-flow 对应能力</th></tr></thead><tbody><tr><td>计算 / 任务编排</td><td>一串步骤按顺序/条件执行</td><td><code>activity</code> 节点 + <code>task</code> + <code>when</code></td></tr><tr><td>业务规则 / 决策</td><td>多条件分支、规则集</td><td><code>exclusive</code>/<code>inclusive</code> 网关 + 表达式 <code>when</code></td></tr><tr><td>可中断可恢复流程</td><td>人工审批、等回调、跨天长流程</td><td><code>context.stop()</code> + 快照持久化 + <code>reverting</code> 恢复</td></tr><tr><td>复杂智能体</td><td>ReActAgent、TeamAgent、Multi-Agent</td><td><code>parallel</code> 并行 + 子图 <code>#sub</code> + <code>Container</code> 组件</td></tr><tr><td>人工任务工作流</td><td>认领 / 审批 / 跳转 / 终止</td><td><code>solon-flow-workflow</code> 子系统</td></tr></tbody></table><h3 id="_1-1-模块全景-java-侧" tabindex="-1">1.1 模块全景（Java 侧） <a class="header-anchor" href="#_1-1-模块全景-java-侧" aria-label="Permalink to &quot;1.1 模块全景（Java 侧）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>solon-flow/                    # 核心引擎（98 个 .java）</span></span>
<span class="line"><span>  ├ org/noear/solon/flow/      # Graph/Node/Link/Engine/Driver/Context/...</span></span>
<span class="line"><span>  ├ driver/                    # AbstractFlowDriver / SimpleFlowDriver</span></span>
<span class="line"><span>  ├ container/                 # MapContainer / SolonContainer</span></span>
<span class="line"><span>  ├ evaluation/                # LiquorEvaluation（默认，Snel + liquor）</span></span>
<span class="line"><span>  ├ intercept/                 # FlowInterceptor / FlowInvocation</span></span>
<span class="line"><span>  ├ integration/               # FlowPlugin / FlowConfigurate（Solon 装配）</span></span>
<span class="line"><span>  ├ aot/                       # GraalVM 原生镜像资源注册</span></span>
<span class="line"><span>  └ util/                      # Stepper（区间迭代器）</span></span>
<span class="line"><span>solon-flow-workflow/           # 工作流子系统（42 个 .java）</span></span>
<span class="line"><span>  ├ WorkflowExecutor(+Default) # 对外门面：claim/find/submit</span></span>
<span class="line"><span>  ├ WorkflowDriver             # 装饰核心 driver，实现「人工任务暂停」</span></span>
<span class="line"><span>  ├ Task/TaskState/TaskAction/WorkflowIntent</span></span>
<span class="line"><span>  ├ StateController            # Actor/Block/NotBlock</span></span>
<span class="line"><span>  └ repository/                # InMemory / Redis</span></span>
<span class="line"><span>solon-flow-projects/           # 第三方表达式引擎适配</span></span>
<span class="line"><span>  ├ solon-flow-eval-aviator    # AviatorEvaluation</span></span>
<span class="line"><span>  ├ solon-flow-eval-beetl      # BeetlEvaluation</span></span>
<span class="line"><span>  └ solon-flow-eval-magic      # MagicEvaluation</span></span>
<span class="line"><span>solon-flow-designer/           # 可视化设计器（Vue 前端，knife4j 风格）</span></span>
<span class="line"><span>solon-flow-dataflow/           # 数据流（设计文档阶段，README only）</span></span></code></pre></div><hr><h2 id="_2-迁移范围-迁什么、不迁什么" tabindex="-1">2. 迁移范围：迁什么、不迁什么 <a class="header-anchor" href="#_2-迁移范围-迁什么、不迁什么" aria-label="Permalink to &quot;2. 迁移范围：迁什么、不迁什么&quot;">​</a></h2><h3 id="_2-1-迁-p0–p2-详见-05-tdd-plan-md" tabindex="-1">2.1 迁（P0–P2，详见 <code>05-tdd-plan.md</code>） <a class="header-anchor" href="#_2-1-迁-p0–p2-详见-05-tdd-plan-md" aria-label="Permalink to &quot;2.1 迁（P0–P2，详见 \`05-tdd-plan.md\`）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>能力</th><th>来源模块</th><th>目标</th></tr></thead><tbody><tr><td>1</td><td>图模型：Graph/Node/Link/Spec + NodeType</td><td><code>solon-flow</code></td><td><code>./flow</code> 根包</td></tr><tr><td>2</td><td>核心引擎：<code>eval</code> 遍历 + <code>node_run</code> + 网关语义</td><td><code>solon-flow</code></td><td><code>./flow</code> 根包</td></tr><tr><td>3</td><td>驱动机制：FlowDriver + AbstractDriver + SimpleDriver</td><td><code>solon-flow.driver</code></td><td><code>./flow/driver</code></td></tr><tr><td>4</td><td>上下文：FlowContext + vars/with/trace/stop</td><td><code>solon-flow</code></td><td><code>./flow</code> 根包</td></tr><tr><td>5</td><td>容器与组件：Container + MapContainer + Task/ConditionComponent</td><td><code>solon-flow.container</code></td><td><code>./flow/container</code></td></tr><tr><td>6</td><td>表达式引擎：Evaluation 接口 + 默认实现</td><td><code>solon-flow.evaluation</code></td><td><code>./flow/evaluation</code>（<strong>默认复用 enjoy</strong>）</td></tr><tr><td>7</td><td>拦截器：FlowInterceptor + FlowInvocation</td><td><code>solon-flow.intercept</code></td><td><code>./flow/intercept</code></td></tr><tr><td>8</td><td>轨迹与恢复：FlowTrace + NodeRecord + <code>reverting</code></td><td><code>solon-flow</code></td><td><code>./flow</code> 根包</td></tr><tr><td>9</td><td>快照序列化：toJson/fromJson（中断/恢复）</td><td><code>solon-flow</code></td><td><code>./flow</code> 根包</td></tr><tr><td>10</td><td>子图调用 / 步数预算 / 临时栈</td><td><code>solon-flow</code></td><td><code>./flow/util</code> + 根包</td></tr><tr><td>11</td><td>YAML/JSON 配置解析 + 图注册</td><td><code>solon-flow.integration</code></td><td><code>./flow</code> 根包（<code>config.Props</code> + <code>embed</code>）</td></tr><tr><td>12</td><td>工作流子系统：Executor/Driver/Task/State*/Repository</td><td><code>solon-flow-workflow</code></td><td><code>./flow/workflow</code></td></tr><tr><td>13</td><td>集成插件：<code>aifei.Plugin</code> 生命周期装配</td><td><code>solon-flow.integration</code></td><td><code>./plugins/flow</code></td></tr><tr><td>14</td><td><strong>内置 MySQL 持久化：<code>MysqlStateRepository</code> + 任务历史</strong></td><td>新增（参考表 <code>bpm_flow_repository</code>/<code>bpm_flow_task</code>）</td><td><code>./plugins/flow</code>（P2，最后一项任务，见 <code>06</code>）</td></tr></tbody></table><h3 id="_2-2-不迁-明确排除" tabindex="-1">2.2 不迁（明确排除） <a class="header-anchor" href="#_2-2-不迁-明确排除" aria-label="Permalink to &quot;2.2 不迁（明确排除）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>项目</th><th>原因</th></tr></thead><tbody><tr><td>A</td><td><strong><code>solon-flow-designer</code></strong>（Vue 可视化设计器）</td><td>纯前端 Web 应用，与 Go 库无关；需要时单独建前端仓库。可在 <code>03-config-and-eval.md</code> 记其 <code>layout</code> schema 契约，保证设计器产物可直接被 flow-go 消费。</td></tr><tr><td>B</td><td><strong><code>solon-flow-dataflow</code></strong></td><td>仍处于设计文档阶段（README only），无实现可迁；列为未来方向。</td></tr><tr><td>C</td><td><strong>GraalVM AOT（<code>aot/FlowRuntimeNativeRegistrar</code>）</strong></td><td>Go 静态编译即原生，<code>//go:embed</code> 已天然「AOT」，无需对应物。</td></tr><tr><td>D</td><td><strong>Solon IoC 耦合（<code>@Configuration</code>/<code>@Bean</code>/<code>Solon.context().getBean</code>）</strong></td><td>aifei-go 无 IoC 容器；用 <code>MapContainer</code> + 命令式装配替代（见 <code>01</code> 第 7 节）。</td></tr><tr><td>E</td><td><strong>snack4 <code>ONode</code> 多态序列化（<code>Write_ClassName</code>+<code>Read_AutoType</code>）</strong></td><td>Go <code>encoding/json</code> 无直接等价；快照 vars 限定为 JSON 原生类型或显式 DTO（见 <code>03</code>）。</td></tr><tr><td>F</td><td><strong>liquor <code>Scripts.eval</code> 任意语句脚本</strong></td><td>无零成本 Go 等价；用 enjoy（条件/表达式/赋值）+ <code>@组件</code>（复杂逻辑）双轨替代（见 <code>03</code>）。</td></tr><tr><td>G</td><td><strong>RedisStateRepository（<code>redisx</code>）</strong></td><td>solon-flow 的 Redis 仓储绑死 <code>redisx</code>；aifei-go <strong>不迁 Redis 实现</strong>，改以内置 MySQL 仓储（<code>MysqlStateRepository</code>，见 <code>06</code>，P2 最后一项任务）。</td></tr></tbody></table><blockquote><p><strong>结论</strong>：迁移后的 flow-go 是一个<strong>自包含、零外部依赖</strong>的流程引擎库，覆盖 solon-flow 的核心编排能力 + 工作流子系统；脚本/语句求值与可视化设计器留作可插拔扩展。</p></blockquote><hr><h2 id="_3-概念词典-java-→-go-命名" tabindex="-1">3. 概念词典（Java → Go 命名） <a class="header-anchor" href="#_3-概念词典-java-→-go-命名" aria-label="Permalink to &quot;3. 概念词典（Java → Go 命名）&quot;">​</a></h2><blockquote><p>完整方法签名对照见 <a href="./01-go-comparison.html"><code>01-go-comparison.md</code></a>。</p></blockquote><table tabindex="0"><thead><tr><th>中文</th><th>Java 概念</th><th>Java 类型</th><th>Go（建议）</th><th>说明</th></tr></thead><tbody><tr><td>流程图</td><td>图 / 流图</td><td><code>Graph</code> / <code>GraphSpec</code></td><td><code>Graph</code> / <code>GraphSpec</code></td><td>点+线；Spec 是可变构建器</td></tr><tr><td>流程节点</td><td>节点 / 流节点</td><td><code>Node</code> / <code>NodeSpec</code> / <code>NodeType</code></td><td><code>Node</code> / <code>NodeSpec</code> / <code>NodeType</code></td><td>可带 task + when</td></tr><tr><td>流程连接线</td><td>连接 / 流连接</td><td><code>Link</code> / <code>LinkSpec</code></td><td><code>Link</code> / <code>LinkSpec</code></td><td>可带 when 条件 + priority</td></tr><tr><td>流程引擎</td><td>引擎 / 流引擎</td><td><code>FlowEngine</code></td><td><code>Engine</code>（包名 <code>flow</code>）</td><td>执行图，注册多图</td></tr><tr><td>流程驱动器</td><td>驱动器</td><td><code>FlowDriver</code></td><td><code>Driver</code></td><td>像 JDBC 驱动，控制执行语义</td></tr><tr><td>流程上下文</td><td>上下文</td><td><code>FlowContext</code></td><td><code>Context</code></td><td>vars 变量域 + trace + eventBus</td></tr><tr><td>流程拦截器</td><td>拦截器</td><td><code>FlowInterceptor</code></td><td><code>Interceptor</code></td><td>AOP，包整次 eval + per-node 回调</td></tr><tr><td>交换器</td><td>交换器</td><td><code>FlowExchanger</code></td><td><code>Exchanger</code></td><td>单次运行的可变状态（步数/栈/标志）</td></tr><tr><td>轨迹</td><td>轨迹</td><td><code>FlowTrace</code> / <code>NodeRecord</code></td><td><code>Trace</code> / <code>NodeRecord</code></td><td>每图最后执行节点 = 恢复点</td></tr><tr><td>任务组件</td><td>任务组件</td><td><code>TaskComponent</code></td><td><code>func(Context, *Node) error</code></td><td><code>@bean</code> 或硬编码</td></tr><tr><td>条件组件</td><td>条件组件</td><td><code>ConditionComponent</code></td><td><code>func(Context) (bool, error)</code></td><td><code>@bean</code> 或硬编码</td></tr><tr><td>表达式引擎</td><td>求值器</td><td><code>Evaluation</code></td><td><code>Evaluation</code></td><td>2 方法：runCondition / runTask</td></tr><tr><td>工作流执行器</td><td>—</td><td><code>WorkflowExecutor</code></td><td><code>workflow.Executor</code></td><td>claim/find/submit</td></tr><tr><td>任务（工作流）</td><td>—</td><td><code>Task</code> / <code>TaskState</code> / <code>TaskAction</code></td><td><code>Task</code> / <code>State</code> / <code>Action</code></td><td>人工任务模型</td></tr><tr><td>状态控制器</td><td>—</td><td><code>StateController</code></td><td><code>StateController</code></td><td>Actor/Block/NotBlock</td></tr><tr><td>状态仓储</td><td>—</td><td><code>StateRepository</code></td><td><code>StateRepository</code></td><td>InMemory（内置）+ MySQL（<code>./plugins/flow</code>，见 06）</td></tr></tbody></table><p><strong>节点类型（<code>NodeType</code>）</strong>：<code>start</code> / <code>end</code> / <code>activity</code> / <code>exclusive</code>（XOR 单选）/ <code>inclusive</code>（OR 多选）/ <code>parallel</code>（AND 全选+汇合）/ <code>loop</code>（循环，<code>$for</code>/<code>$in</code>）。语义详见 <code>02-core-design.md</code>。</p><hr><h2 id="_4-模块地图与依赖" tabindex="-1">4. 模块地图与依赖 <a class="header-anchor" href="#_4-模块地图与依赖" aria-label="Permalink to &quot;4. 模块地图与依赖&quot;">​</a></h2><h3 id="_4-1-在-aifei-go-工作区中的位置" tabindex="-1">4.1 在 aifei-go 工作区中的位置 <a class="header-anchor" href="#_4-1-在-aifei-go-工作区中的位置" aria-label="Permalink to &quot;4.1 在 aifei-go 工作区中的位置&quot;">​</a></h3>`,27)),(e(),l(p,null,{default:t(()=>[i(c,{id:"mermaid-762",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20CORE%5B%22Core%20library%EF%BC%88%E9%9B%B6%E5%A4%96%E9%83%A8%E4%BE%9D%E8%B5%96%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20ENJOY%5B%22enjoy%EF%BC%88%E8%A1%A8%E8%BE%BE%E5%BC%8F%2F%E6%A8%A1%E6%9D%BF%E5%BC%95%E6%93%8E%20%E2%86%92%20%E9%BB%98%E8%AE%A4%20Evaluation%20%E5%90%8E%E7%AB%AF%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20DAMI%5B%22dami%EF%BC%88%E8%BF%9B%E7%A8%8B%E5%86%85%E4%BA%8B%E4%BB%B6%E6%80%BB%E7%BA%BF%20%E2%86%92%20Context.EventBus%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20JSON%5B%22json%22%5D%0A%20%20%20%20%20%20%20%20LOG%5B%22log%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20STANDALONE%5B%22Standalone%20framework%22%5D%0A%20%20%20%20%20%20%20%20FLOW%5B%22flow%EF%BC%88%E6%9C%AC%E8%AE%BE%E8%AE%A1%EF%BC%9A%E6%A0%B8%E5%BF%83%E7%BC%96%E6%8E%92%E5%BC%95%E6%93%8E%20%2B%20%E5%B7%A5%E4%BD%9C%E6%B5%81%EF%BC%9B%E9%9B%B6%E5%A4%96%E9%83%A8%E4%BE%9D%E8%B5%96%EF%BC%8CInMemory%20%E4%BB%93%E5%82%A8%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20NAMI%5B%22nami%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20RUNTIME%5B%22Runtime%22%5D%0A%20%20%20%20%20%20%20%20SERVER%5B%22server%20%2F%20http%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20PLUGIN%5B%22Plugin%EF%BC%88%E5%8F%AF%E9%80%89%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20PFLOW%5B%22plugins%2Fflow%EF%BC%88aifei.Plugin%20%E8%A3%85%E9%85%8D%20%2B%20%E5%86%85%E7%BD%AE%20MysqlStateRepository%20%2B%20%E4%BB%BB%E5%8A%A1%E5%8E%86%E5%8F%B2%EF%BC%9B%E8%A7%81%2006%EF%BC%89%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20TEST%5B%22Example%20%2F%20Test%22%5D%0A%20%20%20%20%20%20%20%20FT%5B%22_test%2Fflow_test%22%5D%0A%20%20%20%20end%0A%20%20%20%20ENJOY%20--%3E%20FLOW%0A%20%20%20%20DAMI%20--%3E%20FLOW%0A"})]),fallback:t(()=>[...o[0]||(o[0]=[s(" Loading... ",-1)])]),_:1})),o[2]||(o[2]=d(`<h3 id="_4-2-flow-内部包结构-建议" tabindex="-1">4.2 <code>./flow</code> 内部包结构（建议） <a class="header-anchor" href="#_4-2-flow-内部包结构-建议" aria-label="Permalink to &quot;4.2 \`./flow\` 内部包结构（建议）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>包</th><th>职责</th><th>依赖</th></tr></thead><tbody><tr><td><code>flow</code>（根）</td><td>Graph/Node/Link/Spec、NodeType、Engine、Exchanger、Context(+default)、Driver 接口、Interceptor 接口、Trace/NodeRecord、Options、Error、TaskDesc/ConditionDesc、Container/Component 接口、Evaluation 接口、加载/注册</td><td><code>enjoy</code>（仅 default eval 间接）、<code>dami</code>（仅 Context.EventBus）、<code>log</code></td></tr><tr><td><code>flow/util</code></td><td><code>Stepper</code>（区间迭代器）</td><td>标准库</td></tr><tr><td><code>flow/container</code></td><td><code>MapContainer</code>（默认）</td><td><code>flow</code> 根接口</td></tr><tr><td><code>flow/evaluation</code></td><td><code>Evaluation</code> 接口 + <code>EnjoyEvaluation</code>（默认，复用 enjoy）</td><td><code>flow</code> 根接口 + <code>enjoy</code></td></tr><tr><td><code>flow/driver</code></td><td><code>AbstractDriver</code>（<code>@/#/$</code> 派发）+ <code>SimpleDriver</code></td><td><code>flow</code> 根 + <code>evaluation</code> + <code>container</code></td></tr><tr><td><code>flow/intercept</code></td><td><code>Interceptor</code> 适配 + <code>Invocation</code> 链</td><td><code>flow</code> 根</td></tr><tr><td><code>flow/workflow</code></td><td>Executor + WorkflowDriver + Task/State/Action/Intent + StateController + InMemoryRepository</td><td><code>flow</code> 根 + <code>flow/driver</code></td></tr></tbody></table><blockquote><p><strong>插件层（<code>./plugins/flow</code>，依赖 <code>./db</code>，见 <a href="./06-mysql-repository.html"><code>06-mysql-repository.md</code></a>）</strong>：</p></blockquote><table tabindex="0"><thead><tr><th>包</th><th>职责</th><th>依赖</th></tr></thead><tbody><tr><td><code>plugins/flow</code></td><td><code>aifei.Plugin</code> 装配：读 <code>flow.*</code> 配置、glob 图资源、构造引擎与 Executor</td><td><code>aifei</code> + <code>config</code> + <code>flow</code> + <code>log</code></td></tr><tr><td><code>plugins/flow</code>（mysql_state）</td><td><strong><code>MysqlStateRepository</code></strong>：<code>StateRepository</code> 实现 + 快照 Save/Load（<code>bpm_flow_repository</code>）</td><td><code>flow</code> + <code>db</code></td></tr><tr><td><code>plugins/flow</code>（mysql_task）</td><td><strong><code>TaskHistoryRecorder</code></strong>：任务流转历史（<code>bpm_flow_task</code>）</td><td><code>flow</code> + <code>db</code></td></tr></tbody></table><blockquote><p>依赖方向严格单向：<code>workflow</code>/<code>driver</code> → 根接口；<code>evaluation</code>/<code>container</code> → 根接口；<code>driver</code> → <code>evaluation</code> + <code>container</code>。无环。</p></blockquote><h3 id="_4-3-go-mod-建议" tabindex="-1">4.3 go.mod（建议） <a class="header-anchor" href="#_4-3-go-mod-建议" aria-label="Permalink to &quot;4.3 go.mod（建议）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>module github.com/crazy-airhead/aifei-go/flow</span></span>
<span class="line"><span>go 1.26</span></span>
<span class="line"><span>require (</span></span>
<span class="line"><span>    github.com/crazy-airhead/aifei-go v0.0.x   // aifei（Plugin 接口）</span></span>
<span class="line"><span>    github.com/crazy-airhead/aifei-go/enjoy v0.0.x</span></span>
<span class="line"><span>    github.com/crazy-airhead/aifei-go/dami v0.0.x</span></span>
<span class="line"><span>    github.com/crazy-airhead/aifei-go/log v0.0.x</span></span>
<span class="line"><span>    github.com/crazy-airhead/aifei-go/config v0.0.x   // 仅 Plugin 装配用</span></span>
<span class="line"><span>    gopkg.in/yaml.v3 // 仅配置解析（config 已传递依赖）</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>并在 <code>go.work</code> 增加 <code>use ./flow</code>；新增测试模块 <code>_test/flow_test</code>（<code>use ./_test/flow_test</code>）。</p><blockquote><p><strong><code>./plugins/flow</code> 是独立模块</strong>（P2）：<code>require</code> <code>aifei</code>/<code>config</code>/<code>db</code>/<code>flow</code>/<code>log</code>（对照 <code>plugins/dataisolate</code> 的 go.mod 模式），MySQL 驱动由应用 <code>db.Init(&quot;mysql&quot;, dsn)</code> 提供。核心 <code>./flow</code> 因此保持零外部依赖、不耦合 db（InMemory 即可全功能运行）。<code>go.work</code> 另加 <code>use ./plugins/flow</code>。</p></blockquote><hr><h2 id="_5-与-aifei-go-现有能力的关系-不重复造轮子" tabindex="-1">5. 与 aifei-go 现有能力的关系（不重复造轮子） <a class="header-anchor" href="#_5-与-aifei-go-现有能力的关系-不重复造轮子" aria-label="Permalink to &quot;5. 与 aifei-go 现有能力的关系（不重复造轮子）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>solon-flow 依赖</th><th>aifei-go 对应</th><th>复用方式</th></tr></thead><tbody><tr><td><code>dami2.DamiBus</code>（<code>Context.eventBus()</code>）</td><td><strong><code>./dami</code></strong>（Send/Listen/Call/Stream/LPC）</td><td><code>Context</code> 懒初始化一个 <code>*dami.Bus</code>，对外暴露 <code>EventBus()</code>；语义等价（send 事件、call 请求-响应）</td></tr><tr><td>liquor <code>Scripts.eval</code> + Snel（条件/任务求值）</td><td><strong><code>./enjoy</code></strong> 表达式引擎（<code>Expr.Eval(scope, ctrl)</code>：算术/比较/逻辑/三元/null-safe/方法调用/字段/赋值/Map/Array）</td><td>默认 <code>EnjoyEvaluation</code> 包装 <code>enjoy.Engine</code>：<code>runCondition</code> = <code>eval</code> 取布尔（null→false，bool→自身，其它→true，<strong>与 Snel 完全一致的真值规则</strong>）；<code>runTask</code> = enjoy 语句求值</td></tr><tr><td>snack4 JSON</td><td><strong><code>./json</code></strong> / <code>encoding/json</code></td><td>快照 <code>MarshalJSON</code>/<code>UnmarshalJSON</code></td></tr><tr><td>snakeyaml</td><td><code>gopkg.in/yaml.v3</code>（config 已用）</td><td>图配置 YAML 解析</td></tr><tr><td>Solon IoC（<code>getBean</code>）</td><td><strong><code>MapContainer</code></strong>（已在 solon-flow 内）</td><td><code>@bean</code> → <code>map[string]any</code> 注册表，类型断言取 <code>TaskComponent</code>/<code>ConditionComponent</code></td></tr><tr><td>slf4j</td><td><strong><code>./log</code></strong></td><td><code>log.Logger</code> 接口</td></tr><tr><td>Solon <code>Plugin</code> 生命周期</td><td><strong><code>aifei.Plugin</code></strong>（<code>Start()</code>/<code>Stop()</code>）</td><td><code>flow.Plugin</code> 实现，命令式装配</td></tr><tr><td><code>ResourceUtil.scanResources</code>（classpath glob）</td><td><code>//go:embed</code> + <code>filepath.Glob</code> + <code>os.ReadFile</code></td><td>图资源加载</td></tr></tbody></table><hr><h2 id="_6-设计原则-贯穿所有后续文档" tabindex="-1">6. 设计原则（贯穿所有后续文档） <a class="header-anchor" href="#_6-设计原则-贯穿所有后续文档" aria-label="Permalink to &quot;6. 设计原则（贯穿所有后续文档）&quot;">​</a></h2><ol><li><strong>零外部依赖</strong>：<code>./flow</code> 仅用标准库 + 内部 <code>enjoy</code>/<code>dami</code>/<code>log</code>/<code>config</code>；不引入 yaegi / cel / redis 客户端等。Redis 仓储走接口，留待 P2 插件。</li><li><strong>类型安全</strong>：能用 Go 泛型的地方不用 <code>any</code>（如 <code>GetAs[T]</code>）；但 vars 本质是 <code>map[string]any</code>，保留 <code>any</code> + 类型断言。</li><li><strong>API 命名</strong>沿用 Java Aifei/solon-flow 习惯（<code>Eval</code>/<code>ClaimTask</code>/<code>SubmitTask</code>/<code>Register</code>），与 aifei-go 现有命名一致；包级工厂函数 <code>flow.NewEngine()</code> 替代 Java 静态工厂。</li><li><strong>并发安全</strong>：<code>Context.vars</code> 用 <code>map</code> + <code>sync.RWMutex</code>（对齐 <code>config</code> 模式）；标志位 <code>atomic.Bool</code>；步数 <code>atomic.Int64</code>；并行网关 <code>errgroup</code>。</li><li><strong>错误模型</strong>：<code>error</code> 返回；引擎内非 <code>flow.Error</code> 的 error 用 <code>flow.Error</code> 包装（带 graphId/nodeId 上下文），等价于 Java 把非 <code>FlowException</code> 包成 <code>FlowException</code>。</li><li><strong>可测试性（TDD 先行）</strong>：核心逻辑全部可被 <code>_test/flow_test</code> 黑盒测试；图用 YAML 字面量定义；不依赖任何外部服务（与 aifei-go 测试约定一致）。</li><li><strong>忠实语义</strong>：遍历顺序、网关默认值（link/node 默认 true、exclusive 默认 false）、<code>reverting</code> 恢复、<code>@/#/$</code> 派发优先级、并行首错优先——逐一对照 Java 实现，测试用例直接搬 solon-flow 的 <code>features/flow/generated</code>。</li></ol><hr><h2 id="_7-可行性结论" tabindex="-1">7. 可行性结论 <a class="header-anchor" href="#_7-可行性结论" aria-label="Permalink to &quot;7. 可行性结论&quot;">​</a></h2><ul><li><strong>可迁</strong>：核心引擎 + 工作流子系统约 90% 语义等价；最大的语言鸿沟（任意 Java 语句脚本）有 enjoy + 组件双轨兜底，且 <code>Evaluation</code> 接口预留扩展。</li><li><strong>收益</strong>：aifei-go 获得一流的流程编排/规则/工作流能力，与已有 <code>dami</code>（事件）、<code>db</code>（持久化，可做 StateRepository 后端）、<code>server</code>（HTTP 暴露工作流 API）天然组合，形成「Just Service + 流程编排」闭环。</li><li><strong>风险</strong>：①<code>reverting</code> 恢复在多入度网关下的边界（Java 本身有 caveat，见 <code>02</code> 第 6 节，需测试固化）；②enjoy 与 Snel 的表达式语法<strong>子集差异</strong>（个别操作符/内置函数），需在 <code>03</code> 列出差异表并补齐或标注不支持；③快照多态类型（vars 存自定义结构）需约束为 JSON 友好类型。</li><li><strong>工作量预估</strong>：核心（P0）≈ 1800–2200 行 Go；工作流（P1）≈ 600–800 行；配置/集成/快照 ≈ 400–600 行；测试 ≈ 与实现 1:1。分期与验收见 <code>05-tdd-plan.md</code>。</li></ul><hr><h2 id="_8-阅读路线" tabindex="-1">8. 阅读路线 <a class="header-anchor" href="#_8-阅读路线" aria-label="Permalink to &quot;8. 阅读路线&quot;">​</a></h2><ol><li>先读本篇（总览 + 范围 + 概念）。</li><li><a href="./01-go-comparison.html"><code>01-go-comparison.md</code></a>：逐类型/方法对照，Java 特性 → Go 惯用法。</li><li><a href="./02-core-design.html"><code>02-core-design.md</code></a>：核心引擎的 Go 接口签名 + 执行模型 + 并发。</li><li><a href="./03-config-and-eval.html"><code>03-config-and-eval.md</code></a>：配置 schema、加载注册、快照、表达式、集成插件。</li><li><a href="./04-workflow-design.html"><code>04-workflow-design.md</code></a>：工作流子系统的状态机与状态仓储。</li><li><a href="./05-tdd-plan.html"><code>05-tdd-plan.md</code></a>：TDD 分期路线、每期测试用例、验收标准。</li><li><a href="./06-mysql-repository.html"><code>06-mysql-repository.md</code></a>：内置 MySQL 状态仓储 + 任务历史（最后一项任务）。</li></ol>`,21))])}const y=a(g,[["render",f]]);export{b as __pageData,y as default};
